import Foundation

/// Exact user-supplied application marks embedded in the signed app. The UI
/// renders these bytes directly—never inside a Nexus-created color tile.
enum NexProviderIconCatalog {
    private static let encoded: [String: (String, String)] = [
        "terminal": ("", "terminal"),
        "finder": ("", "folder"),
        "calendar": ("", "calendar"),
        "messages": ("", "message.fill"),
        "notion": ("", "doc.text"),
        "photos": ("", "photo"),
        "preview": ("", "doc.richtext"),
        "slack": ("", "number"),
        "vscode": ("", "chevron.left.forwardslash.chevron.right"),
        "xcode": ("", "hammer"),
        "google": ("", "globe"),
        "github": ("", "chevron.left.forwardslash.chevron.right")
    ]

    static func icon(for action: String) -> ToolIconSource {
        if action == "nex_cli_task" { return .systemSymbol("terminal") }
        if action.hasPrefix("memory_") || action == "conversation_recall" { return .asset(name: "Obsidian", fallbackSystemName: "diamond.fill") }
        if action == "web_search" || action.hasPrefix("chrome.") || action.hasPrefix("browser.") { return .asset(name: "Chrome", fallbackSystemName: "globe") }
        if action.hasPrefix("youtube_") { return .asset(name: "YouTube", fallbackSystemName: "play.rectangle.fill") }
        let key: String
        switch action.split(separator: ".").first.map(String.init) ?? action {
        case "terminal": key = "terminal"
        case "finder": key = "finder"
        case "calendar": key = "calendar"
        case "messages": key = "messages"
        case "notion": key = "notion"
        case "photos": key = "photos"
        case "preview": key = "preview"
        case "slack": key = "slack"
        case "vscode": key = "vscode"
        case "xcode": key = "xcode"
        case "gmail", "google", "contacts": key = "google"
        case "github", "git": key = "github"
        default: return .systemSymbol(fallback(for: action))
        }
        guard let value = encoded[key], let data = Data(base64Encoded: value.0) else { return .systemSymbol(fallback(for: action)) }
        return .image(data: data, fallbackSystemName: value.1)
    }

    static func fallback(for action: String) -> String {
        if action.hasPrefix("spotify.") { return "music.note" }
        if action.hasPrefix("discord.") { return "bubble.left.and.bubble.right" }
        if action.hasPrefix("applications.") { return "app.dashed" }
        if action.hasPrefix("system.") { return "gearshape" }
        return "wrench.and.screwdriver"
    }
}

